	e := apitest.New(t)
	e.DNS.Set("loopback.example", "127.0.0.1")
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	for _, bad := range []string{"http://hooks.acme.example/", "https://user:pass@hooks.acme.example/", "https://169.254.169.254/latest/meta-data", "https://127.0.0.1:6379/", "https://loopback.example/"} {
		if r := e.Do("POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": bad, "events": []string{"*"}}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_url" {
			t.Fatalf("create %q: %s", bad, r)
		}
		if r := e.Do("PATCH", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, map[string]any{"url": bad}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_url" {
			t.Fatalf("update to %q: %s", bad, r)
		}
	}
	if got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID); got.URL != "https://hooks.acme.example/tally" {
		t.Fatalf("refused update changed the URL to %q", got.URL)
	}
}

