219	func (s *Service) deliver(ctx context.Context, d store.Delivery) {
220		status, errText := 0, ""
221		ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
222		e, eok := s.store.EventByID(d.EventID)
223		switch {
224		case !ok || !ep.Enabled:
225			errText = "the endpoint is disabled or was deleted"
226		case !eok:
227			errText = "the event no longer exists"
228		default:
229			status, errText = s.send(ctx, ep, e)
230		}
231		now := s.clock.Now()
232		_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
233			d.Attempts++
234			d.LastAttemptAt = &now
235			d.NextAttemptAt = nil
236			d.ResponseStatus = status
237			d.Error = errText
238			if errText == "" {
239				d.Status = store.DeliverySucceeded
240			} else {
241				d.Status = store.DeliveryFailed
242			}
243			return nil
244		})
245	}
