247	// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
248	func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
249		body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
250		if err != nil {
251			return 0, err.Error()
252		}
253		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
254		defer cancel()
255		// DNS may have changed since the URL was saved, so the host is checked again before anything is sent.
256		u, err := url.Parse(ep.URL)
257		if err != nil {
258			return 0, err.Error()
259		}
260		addrs, err := s.hostAddrs(ctx, u.Hostname())
261		if err != nil {
262			return 0, fmt.Sprintf("the endpoint's host %q does not resolve: %v", u.Hostname(), err)
263		}
264		for _, a := range addrs {
265			if !publicAddr(a) {
266				return 0, fmt.Sprintf("the endpoint's address is not public: %q resolves to %s", u.Hostname(), a)
267			}
268		}
269		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
270		if err != nil {
271			return 0, err.Error()
272		}
273		req.Header.Set("Content-Type", "application/json")
274		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
275		req.Header.Set("Tally-Event-Id", e.ID)
276		req.Header.Set("Tally-Event-Type", e.Type)
277		req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
278		resp, err := s.doer.Do(req)
279		if err != nil {
280			return 0, err.Error()
281		}
282		defer resp.Body.Close()
283		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
284		if resp.StatusCode < 200 || resp.StatusCode > 299 {
285			return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)

